import React from 'react';

export default function ActivityFeed({ activities }) {
  return (
    <ul className="space-y-2 text-sm text-gray-700">
      {activities.map((item) => (
        <li key={item.id}>• {item.text}</li>
      ))}
    </ul>
  );
}
